        return sum(
            tile[i][j] == 8 and other[i][j] != 8
            for other in tiles
            for i in range(5)
            for j in range(5)
        )

    pattern = min(tiles, key=damage)
    output = [row[:] for row in pattern]

    # Each colored shape has a single distinguished cell. Locate it by
    # descending blue, then choose the cell that belongs to the fewest
    # 2x2 square arrangements of cells of that same color.
    for color in (4, 0, 2):
        positions = [(r, c) for r in range(5) for c in range(5)
                     if pattern[r][c] == color]
        if not positions:
            continue

        square_membership = {p: 0 for p in positions}
        position_set = set(positions)
        for r in range(4):
            for c in range(4):
                members = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                present = [p for p in members if p in position_set]
                if len(present) == 3:
                    for p in present:
                        square_membership[p] += 1

        target = min(positions, key=lambda p: square_membership[p])
        output[target[0]][target[1]] = 1

    return output
