from collections import Counter

def transform(grid):
    tiles = [
        [row[c:c + 5] for row in grid[r:r + 5]]
        for r in range(0, len(grid), 6)
        for c in range(0, len(grid[0]), 6)
    ]

    # Restore the repeated pattern using the majority at each position.
    pattern = [
        [Counter(tile[r][c] for tile in tiles).most_common(1)[0][0]
         for c in range(5)]
        for r in range(5)
    ]

    # The unique damaged tile has background cells in place of pattern cells.
    damaged = max(
        tiles,
        key=lambda tile: sum(
            tile[r][c] != pattern[r][c]
            for r in range(5)
            for c in range(5)
        )
    )

    return [
        [1 if damaged[r][c] != pattern[r][c] else pattern[r][c]
         for c in range(5)]
        for r in range(5)
    ]
